use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Role {
    Knight,
    Knave,
    Spy,
}

impl fmt::Display for Role {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let s = match self {
            Role::Knight => "knight",
            Role::Knave => "knave",
            Role::Spy => "spy",
        };
        write!(f, "{}", s)
    }
}

/// Check whether a person making a statement is consistent with their role.
/// - Knights must tell the truth (statement must be true).
/// - Knaves must lie (statement must be false).
/// - Spies may do either, so they're always consistent.
fn consistent(role: Role, statement: bool) -> bool {
    match role {
        Role::Knight => statement,
        Role::Knave => !statement,
        Role::Spy => true,
    }
}

fn main() {
    let roles = [Role::Knight, Role::Knave, Role::Spy];
    let names = ["Alice", "Bob", "Charlie"];

    let mut solutions = Vec::new();

    // Try every permutation of roles assigned to (Alice, Bob, Charlie).
    for &a in &roles {
        for &b in &roles {
            for &c in &roles {
                // Each role must be used exactly once.
                if a == b || a == c || b == c {
                    continue;
                }

                // Statements:
                // Alice:   "Charlie is a knave."
                // Bob:     "Alice is a knight."
                // Charlie: "I am the spy."
                let alice_stmt = c == Role::Knave;
                let bob_stmt = a == Role::Knight;
                let charlie_stmt = c == Role::Spy;

                if consistent(a, alice_stmt)
                    && consistent(b, bob_stmt)
                    && consistent(c, charlie_stmt)
                {
                    solutions.push((a, b, c));
                }
            }
        }
    }

    println!("Found {} valid assignment(s):", solutions.len());
    for (a, b, c) in &solutions {
        let assignment = [(*a, "Alice"), (*b, "Bob"), (*c, "Charlie")];
        for (role, name) in assignment.iter().zip(names.iter()) {
            // Just printing each person's role:
            println!("  {} = {}", name, role.0);
            let _ = role.1; // silence unused warning from tuple form
        }
        println!(
            "  -> Alice: {}, Bob: {}, Charlie: {}",
            a, b, c
        );
        println!();
    }

    // Verify the expected answer.
    let expected = (Role::Knight, Role::Spy, Role::Knave);
    assert_eq!(solutions.len(), 1, "Puzzle should have a unique solution");
    assert_eq!(solutions[0], expected, "Solution doesn't match expected answer");
    println!("Verified: Alice=knight, Bob=spy, Charlie=knave is the unique solution.");
}
```

